import { Link, useLocation } from 'react-router-dom';
import { 
  Home, ShoppingCart, List, Heart, MessageSquare, 
  Truck, TrendingUp, Users, FileText, Settings 
} from 'lucide-react';

const navItems = [
  { name: 'Dashboard', path: '/', icon: Home },
  { name: 'Marketplace', path: '/marketplace', icon: ShoppingCart },
  { name: 'My Orders', path: '/orders', icon: List },
  { name: 'Saved Items', path: '/saved', icon: Heart },
  { name: 'Messages', path: '/messages', icon: MessageSquare, badge: 2 },
  { name: 'Transport & Logistics', path: '/transport', icon: Truck },
  { name: 'Price Trends', path: '/trends', icon: TrendingUp },
  { name: 'Farmers & Partners', path: '/farmers', icon: Users },
  { name: 'Reports', path: '/reports', icon: FileText },
  { name: 'Settings', path: '/settings', icon: Settings },
];

export const Sidebar = () => {
  const location = useLocation();

  return (
    <aside className="w-64 bg-farmGreen text-white h-screen flex flex-col fixed left-0 top-0 shadow-lg z-20">
      {/* Brand Header */}
      <div className="p-6 flex items-center gap-3">
        <div className="w-8 h-8 bg-white text-farmGreen rounded-full flex items-center justify-center font-bold text-sm">
          FL
        </div>
        <h1 className="text-2xl font-bold tracking-tight">FarmLink</h1>
      </div>

      {/* Navigation */}
      <nav className="flex-1 px-4 space-y-1.5 overflow-y-auto custom-scrollbar">
        {navItems.map((item) => {
          const isActive = location.pathname === item.path || (item.path === '/marketplace' && location.pathname === '/');
          
          return (
            <Link 
              key={item.name} 
              to={item.path} 
              className={`flex items-center justify-between p-3 rounded-lg font-medium transition-colors ${
                isActive ? 'bg-white text-farmGreen shadow-sm' : 'text-white hover:bg-white/10'
              }`}
            >
              <div className="flex items-center gap-3">
                <item.icon size={20} />
                <span>{item.name}</span>
              </div>
              {item.badge && (
                <span className="bg-red-500 text-white text-xs px-2 py-0.5 rounded-full">
                  {item.badge}
                </span>
              )}
            </Link>
          );
        })}
      </nav>

      {/* Bottom Promotional Widget */}
      <div className="p-5">
        <div className="bg-farmGreen-dark p-4 rounded-xl border border-white/10">
          <p className="text-sm font-semibold text-white">Support Local Farmers</p>
          <p className="text-xs text-green-100 mt-1">Stronger Communities</p>
          <p className="text-xs text-green-100">A Food Secure Africa</p>
        </div>
      </div>
    </aside>
  );
};
